package app.cellalerthook.domain

import kotlinx.serialization.Serializable

/** How the app came to see an alert. Each value has its own evidence and failure modes. */
enum class CaptureMethod(val wireName: String) {
    /** Row read from the system Cell Broadcast history provider. Structured and OS-sourced. */
    CELL_BROADCAST_PROVIDER("cell_broadcast_provider"),

    /** Text read from the alert window through an AccessibilityService. */
    ACCESSIBILITY("accessibility"),

    /** Text read from a posted notification. */
    NOTIFICATION("notification"),

    /** Generated by the operator's test tools. */
    SIMULATION("simulation"),

    /** Reserved for future receivers such as a USB modem or a privileged companion. */
    EXTERNAL("external"),
}

/** What was actually observed, kept separate from how it was captured. */
enum class AlertSource(val wireName: String) {
    ANDROID_CELL_BROADCAST("android_cell_broadcast"),
    ANDROID_SYSTEM_ALERT_UI("android_system_alert_ui"),
    ANDROID_SYSTEM_NOTIFICATION("android_system_notification"),
    UNVERIFIED_APP_UI("unverified_app_ui"),
    SIMULATION("simulation"),
}

/**
 * How far the origin of an event has been established.
 *
 * Even [CELL_BROADCAST_STACK] only states that the OS Cell Broadcast stack delivered the message.
 * Cell Broadcast has no over-the-air signature, so it never proves government authorship.
 */
enum class VerificationStatus(val rank: Int, val wireName: String) {
    SIMULATED(0, "simulated"),
    UNVERIFIED(1, "unverified"),
    SYSTEM_COMPONENT_UI(2, "system_component_ui"),

    /** Provider row on a debuggable build, where a lab test hook could have produced it. */
    CELL_BROADCAST_STACK_LAB(3, "cell_broadcast_stack_lab"),

    /** Provider row on a release-signed user build. */
    CELL_BROADCAST_STACK(4, "cell_broadcast_stack"),
}

enum class Confidence(val wireName: String) {
    LOW("low"),
    MEDIUM("medium"),
    HIGH("high"),
}

/** Only ever taken from CMAS fields delivered by the OS, never inferred from message text. */
enum class Severity(val wireName: String) {
    EXTREME("extreme"),
    SEVERE("severe"),
    UNKNOWN("unknown"),
}

/** Trust in the package that produced a piece of UI text. */
enum class OriginTrust {
    /** Installed in a system partition or the Cell Broadcast APEX. */
    SYSTEM_IMAGE,

    /** On the allowlist but installed as an ordinary app. */
    USER_INSTALLED,

    /** This application, which only ever produces simulated alerts. */
    SELF,

    UNKNOWN,
}

enum class DeliveryStatus {
    PENDING,
    DELIVERED,

    /** The server refused the event in a way retrying cannot fix. */
    REJECTED,

    /** Local safety policy prevented sending, for example a misrouted simulation. */
    BLOCKED,
}

enum class ObservationOutcome {
    CREATED,
    DUPLICATE,
    UPGRADED,
    REJECTED,
}

/** Structured fields of a provider row. Absent for anything read from UI text. */
@Serializable
data class CellBroadcastMetadata(
    val rowId: Long,
    val messageId: Int,
    val serialNumber: Int,
    val plmn: String?,
    val lac: Int?,
    val cid: Int?,
    val slotIndex: Int?,
    val subscriptionId: Int?,
    val receivedTimeMs: Long,
    val messageFormat: Int?,
    val messagePriority: Int?,
    val dataCodingScheme: Int?,
    val cmasMessageClass: Int?,
    val cmasCategory: Int?,
    val cmasResponseType: Int?,
    val cmasSeverity: Int?,
    val cmasUrgency: Int?,
    val cmasCertainty: Int?,
    val etwsWarningType: Int?,
    val displayed: Boolean?,
) {
    /** Geographic scope and message code stay stable across repeats of the same alert. */
    val dedupKey: String
        get() = "cb|${plmn.orEmpty()}|$messageId|$serialNumber"

    /** 3GPP TS 23.041 serial number: 2 bits scope, 10 bits message code, 4 bits update. */
    val geographicalScope: Int get() = (serialNumber shr 14) and 0x3
    val messageCode: Int get() = (serialNumber shr 4) and 0x3FF
    val updateNumber: Int get() = serialNumber and 0xF
}

/**
 * Android 15+ replaces a notification's text for ordinary listeners when it looks like a one-time
 * code. An alert quoting a number such as 1122 qualifies, so this stands in for text we never saw.
 */
object HiddenAlertText {
    /** The wire contract requires a non-empty message. */
    const val MESSAGE = "[Android hid this alert's text. Read it on the phone. | أخفى أندرويد نص هذا التنبيه. اقرأه على الهاتف.]"
    const val NOTE = "text_hidden_by_android"
}

/** What a detector saw, before any interpretation. */
data class RawAlertObservation(
    val method: CaptureMethod,
    val observedAtMs: Long,
    val title: String?,
    val body: String?,
    val originPackage: String?,
    val originClass: String?,
    val originTrust: OriginTrust,
    val languageHint: String? = null,
    val cellBroadcast: CellBroadcastMetadata? = null,
    val simulated: Boolean = false,
    /** Found by a catch-up scan rather than a live callback. */
    val catchUp: Boolean = false,
    /** Set when Android hid the text. Identifies the notification, since there is no text to compare. */
    val hiddenTextKey: String? = null,
    /** A detector that can read alert text was working when this was seen. */
    val textDetectorActive: Boolean = false,
)

/** Where the device stands, used to keep lab results apart from field results. */
data class BuildProvenance(
    val buildType: String,
    val buildTags: String,
) {
    /** A retail build: the framework test hook that injects PDUs does not exist here. */
    val isProductionBuild: Boolean
        get() = buildType == "user" && buildTags.contains("release-keys")
}
